    const trie = new Trie();
    for (let word of wordDict) {
        trie.insert(word);
    }

    const dp = new Array(s.length + 1).fill(false);
    dp[s.length] = true;

    let t = 0;
    for (let w of wordDict) {
        t = Math.max(t, w.length);
    }

    for (let i = s.length; i >= 0; i--) {
        for (let j = i; j < Math.min(s.length, i + t); j++) {
            if (trie.search(s, i, j)) {
                dp[i] = dp[j + 1];
                if (dp[i]) {
